library(shiny)
library(tidyverse)
library(plotly)
library(DT)

payroll_data <- read_csv("mlb_model1_project_data_2011_2025.csv")
revenue_data <- read_csv("mlb_model2_project_data_2017_2025.csv")

payroll_effect <- 0.0273665
payroll_effect_se <- 0.0144992
revenue_effect <- 0.4535044

gini <- function(x) {
  x <- sort(x)
  n <- length(x)
  (2 * sum(seq_len(n) * x) / (n * sum(x))) - (n + 1) / n
}

clamp <- function(x, low, high) {
  pmax(low, pmin(high, x))
}

rescale01 <- function(x) {
  good <- is.finite(x)

  if (sum(good) == 0) {
    return(rep(0.5, length(x)))
  }

  lo <- min(x[good])
  hi <- max(x[good])

  if (abs(hi - lo) < 0.0000001) {
    return(rep(0.5, length(x)))
  }

  result <- (x - lo) / (hi - lo)
  result[!good] <- 0.5
  result
}

fmt1 <- function(x) {
  sprintf("%.1f", x)
}

fmt2 <- function(x) {
  sprintf("%.2f", x)
}

fmt3 <- function(x) {
  sprintf("%.3f", x)
}

money_text <- function(x, digits = 1) {
  number <- if (digits == 1) {
    sprintf("%.1f", abs(x))
  } else {
    sprintf("%.2f", abs(x))
  }

  paste0(
    ifelse(x >= 0, "+$", "-$"),
    number,
    "M"
  )
}

percent_text <- function(x, digits = 1) {
  number <- if (digits == 1) {
    sprintf("%.1f", abs(x))
  } else {
    sprintf("%.2f", abs(x))
  }

  paste0(
    ifelse(x > 0, "+", ifelse(x < 0, "-", "")),
    number,
    "%"
  )
}

score_text <- function(x) {
  paste0(
    sprintf("%.1f", x),
    "/100"
  )
}

metric_card <- function(label, output_id, explanation) {
  div(
    class = "metric",
    div(
      class = "metric-label",
      label
    ),
    div(
      class = "metric-value",
      textOutput(output_id)
    ),
    div(
      class = "metric-help",
      explanation
    )
  )
}

formula_box <- function(tex) {
  withMathJax(
    div(
      class = "formula-box",
      HTML(
        paste0(
          "\\[",
          tex,
          "\\]"
        )
      )
    )
  )
}

historical_efficiency <- payroll_data %>%
  filter(
    Year >= 2016,
    Year <= 2025,
    Year != 2020
  ) %>%
  mutate(
    Relative_Winning = Win_Pct / 0.500,
    Payroll_Efficiency = Relative_Winning / Payroll_Index
  ) %>%
  group_by(Team_ID) %>%
  summarise(
    Avg_Historical_Efficiency = mean(
      Payroll_Efficiency,
      na.rm = TRUE
    ),
    .groups = "drop"
  )

base <- payroll_data %>%
  filter(Year == 2025) %>%
  transmute(
    Team_ID,
    Team_Name,
    Payroll_M = Payroll_Opening_Day / 1000000,
    Win_Pct
  ) %>%
  inner_join(
    revenue_data %>%
      filter(Year == 2025) %>%
      select(
        Team_ID,
        Revenue_Millions
      ),
    by = "Team_ID"
  ) %>%
  left_join(
    historical_efficiency,
    by = "Team_ID"
  )

base_avg_payroll <- mean(base$Payroll_M)
base_total_payroll <- sum(base$Payroll_M)
base_gini <- gini(base$Payroll_M)
baseline_win_spread <- sd(base$Win_Pct * 162)
baseline_prearb_pool <- 50
baseline_modeled_comp <- base_total_payroll + baseline_prearb_pool

base <- base %>%
  mutate(
    Model3_Wins_From_25M =
      payroll_effect *
      (
        log(
          (Payroll_M + 25) /
            base_avg_payroll
        ) -
          log(
            Payroll_M /
              base_avg_payroll
          )
      ) *
      162
  )

