mlb_proposal_policy <- function() {
  list(
    upper_rule = "cap",
    upper_value = 258.2,
    upper_tax_rate = 0,
    lower_rule = "floor",
    lower_value = 180.2,
    lower_tax_rate = 0,
    revenue_sharing = 20,
    required_spending = 0,
    central_media = TRUE,
    player_revenue_share = 50,
    minimum_salary_under2 = 0.90,
    minimum_salary_2plus = 1.00,
    prearb_pool = 65,
    arbitration = "3",
    free_agency = "5_age30",
    qualifying_offer = FALSE
  )
}

simulate_policy <- function(
    policy,
    payroll_coef = payroll_effect,
    behavior_multiplier = 1,
    full = TRUE
) {
  contributions <-
    base$Revenue_Millions *
    (
      policy$revenue_sharing /
        100
    )

  league_pool <- sum(contributions)
  equal_share <- league_pool / nrow(base)
  net_transfer <- equal_share - contributions

  required_payroll_from_sharing <-
    pmax(
      net_transfer,
      0
    ) *
    (
      policy$required_spending /
        100
    )

  new_payroll <-
    base$Payroll_M +
    required_payroll_from_sharing

  if (policy$lower_rule == "floor") {
    new_payroll <-
      pmax(
        new_payroll,
        policy$lower_value
      )
  }

  if (policy$lower_rule == "tax") {
    lower_gap <-
      pmax(
        policy$lower_value -
          new_payroll,
        0
      )

    lower_response <-
      clamp(
        (
          policy$lower_tax_rate /
            100
        ) *
          behavior_multiplier,
        0,
        1
      )

    new_payroll <-
      new_payroll +
      lower_gap *
      lower_response
  }

  if (policy$upper_rule == "cap") {
    new_payroll <-
      pmin(
        new_payroll,
        policy$upper_value
      )
  }

  if (policy$upper_rule == "cbt") {
    upper_excess <-
      pmax(
        new_payroll -
          policy$upper_value,
        0
      )

    upper_response <-
      clamp(
        (
          policy$upper_tax_rate /
            100
        ) *
          behavior_multiplier,
        0,
        1
      )

    new_payroll <-
      new_payroll -
      upper_excess *
      upper_response
  }

  scenario_avg_payroll <- mean(new_payroll)

  current_relative <-
    base$Payroll_M /
    base_avg_payroll

  new_relative <-
    new_payroll /
    scenario_avg_payroll

  raw_change_win_pct <-
    payroll_coef *
    (
      log(new_relative) -
        log(current_relative)
    )

  change_win_pct <-
    raw_change_win_pct -
    mean(raw_change_win_pct)

  change_wins <-
    change_win_pct *
    162

  new_win_pct <-
    base$Win_Pct +
    change_win_pct

  new_wins <-
    new_win_pct *
    162

  revenue_change <-
    base$Revenue_Millions *
    (
      exp(
        revenue_effect *
          change_win_pct
      ) -
        1
    )

  cbt_tax <-
    rep(
      0,
      nrow(base)
    )

  low_spending_tax <-
    rep(
      0,
      nrow(base)
    )

  if (policy$upper_rule == "cbt") {
    cbt_tax <-
      pmax(
        new_payroll -
          policy$upper_value,
        0
      ) *
      (
        policy$upper_tax_rate /
          100
      )
  }

  if (policy$lower_rule == "tax") {
    low_spending_tax <-
      pmax(
        policy$lower_value -
          new_payroll,
        0
      ) *
      (
        policy$lower_tax_rate /
          100
      )
  }

  payroll_change <-
    new_payroll -
    base$Payroll_M

  added_payroll <-
    pmax(
      payroll_change,
      0
    )

  if (sum(added_payroll) > 0) {
    recipient_efficiency <-
      weighted.mean(
        base$Avg_Historical_Efficiency,
        added_payroll,
        na.rm = TRUE
      )

    recipient_marginal_wins <-
      weighted.mean(
        base$Model3_Wins_From_25M,
        added_payroll,
        na.rm = TRUE
      )
  } else {
    recipient_efficiency <- NA_real_
    recipient_marginal_wins <- NA_real_
  }

  total_payroll <- sum(new_payroll)

  payroll_change_total <-
    total_payroll -
    base_total_payroll

  new_gini <-
    gini(new_payroll)

  new_win_spread <-
    sd(new_wins)

  competitive_balance_change <-
    (
      (
        baseline_win_spread -
          new_win_spread
      ) /
        baseline_win_spread
    ) *
    100

  modeled_player_comp <-
    total_payroll +
    policy$prearb_pool

  total_revenue_change <-
    sum(revenue_change)

  direct_club_effect <-
    total_revenue_change -
    payroll_change_total

  metrics <- list(
    total_payroll = total_payroll,
    payroll_change = payroll_change_total,
    player_comp = modeled_player_comp,
    player_comp_change =
      modeled_player_comp -
      baseline_modeled_comp,
    gini = new_gini,
    win_spread = new_win_spread,
    competitive_balance_change =
      competitive_balance_change,
    revenue_change =
      total_revenue_change,
    club_effect =
      direct_club_effect,
    cbt_tax =
      sum(cbt_tax),
    low_spending_tax =
      sum(low_spending_tax),
    recipient_efficiency =
      recipient_efficiency,
    recipient_marginal_wins =
      recipient_marginal_wins
  )

  if (!full) {
    return(
      list(
        metrics = metrics
      )
    )
  }

  team <- tibble(
    Team_ID = base$Team_ID,
    Team_Name = base$Team_Name,
    Original_Payroll_M = base$Payroll_M,
    New_Payroll_M = new_payroll,
    Payroll_Change_M = payroll_change,
    Original_Wins = base$Win_Pct * 162,
    Predicted_Wins = new_wins,
    Change_Wins = change_wins,
    Historical_Efficiency =
      base$Avg_Historical_Efficiency,
    Model3_Wins_From_25M =
      base$Model3_Wins_From_25M,
    Revenue_Change_M =
      revenue_change,
    Direct_Club_Effect_M =
      revenue_change -
      payroll_change,
    CBT_Exposure_M =
      cbt_tax,
    Low_Spending_Tax_M =
      low_spending_tax
  )

  list(
    team = team,
    metrics = metrics
  )
}

negotiation_scores <- function(
    policy,
    metrics
) {
  payroll_equality_score <-
    clamp(
      50 +
        (
          base_gini -
            metrics$gini
        ) *
        250,
      0,
      100
    )

  win_balance_score <-
    clamp(
      50 +
        metrics$competitive_balance_change *
        4,
      0,
      100
    )

  mlb_balance <-
    0.55 *
    win_balance_score +
    0.45 *
    payroll_equality_score

  mlb_club_cost <-
    clamp(
      60 -
        metrics$payroll_change /
        10,
      0,
      100
    )

  media_score <-
    ifelse(
      policy$central_media,
      90,
      45
    )

  player_share_alignment <-
    clamp(
      100 -
        abs(
          policy$player_revenue_share -
            50
        ) *
        10,
      0,
      100
    )

  mlb_revenue_structure <-
    0.60 *
    media_score +
    0.40 *
    player_share_alignment

  mlb_upper_alignment <-
    if (policy$upper_rule == "cap") {
      clamp(
        100 -
          abs(
            policy$upper_value -
              258.2
          ) *
          1.2,
        50,
        100
      )
    } else if (policy$upper_rule == "cbt") {
      55
    } else {
      30
    }

  mlb_lower_alignment <-
    if (policy$lower_rule == "floor") {
      clamp(
        100 -
          abs(
            policy$lower_value -
              180.2
          ) *
          1.2,
        50,
        100
      )
    } else if (policy$lower_rule == "tax") {
      60
    } else {
      30
    }

  mlb_free_agency_alignment <-
    ifelse(
      policy$free_agency ==
        "5_age30",
      90,
      55
    )

  mlb_qo_alignment <-
    ifelse(
      policy$qualifying_offer,
      45,
      90
    )

  mlb_policy_alignment <-
    mean(
      c(
        mlb_upper_alignment,
        mlb_lower_alignment,
        mlb_free_agency_alignment,
        mlb_qo_alignment
      )
    )

  mlb_score <-
    0.30 *
    mlb_balance +
    0.25 *
    mlb_club_cost +
    0.20 *
    mlb_revenue_structure +
    0.25 *
    mlb_policy_alignment

  mlbpa_compensation <-
    clamp(
      50 +
        metrics$player_comp_change /
        10,
      0,
      100
    )

  mlbpa_market_freedom <-
    if (policy$upper_rule == "cap") {
      15
    } else if (policy$upper_rule == "cbt") {
      70
    } else {
      100
    }

  under2_score <-
    clamp(
      (
        (
          policy$minimum_salary_under2 -
            0.78
        ) /
          (
            1.50 -
              0.78
          )
      ) *
        100,
      0,
      100
    )

  plus2_score <-
    clamp(
      (
        (
          policy$minimum_salary_2plus -
            0.78
        ) /
          (
            1.50 -
              0.78
          )
      ) *
        100,
      0,
      100
    )

  prearb_score <-
    clamp(
      (
        (
          policy$prearb_pool -
            50
        ) /
          100
      ) *
        100,
      0,
      100
    )

  mlbpa_early_pay <-
    0.35 *
    under2_score +
    0.35 *
    plus2_score +
    0.30 *
    prearb_score

  arbitration_score <-
    ifelse(
      policy$arbitration == "2",
      90,
      55
    )

  free_agency_score <-
    ifelse(
      policy$free_agency ==
        "5_age30",
      90,
      55
    )

  qo_score <-
    ifelse(
      policy$qualifying_offer,
      45,
      90
    )

  mlbpa_player_rights <-
    mean(
      c(
        arbitration_score,
        free_agency_score,
        qo_score
      )
    )

  lower_spending_score <-
    if (policy$lower_rule == "floor") {
      90
    } else if (policy$lower_rule == "tax") {
      75
    } else {
      40
    }

  required_spending_score <-
    clamp(
      40 +
        policy$required_spending *
        0.60,
      0,
      100
    )

  revenue_sharing_score <-
    clamp(
      40 +
        policy$revenue_sharing *
        1.20,
      0,
      100
    )

  mlbpa_spending_incentives <-
    mean(
      c(
        lower_spending_score,
        required_spending_score,
        revenue_sharing_score
      )
    )

  mlbpa_score <-
    0.30 *
    mlbpa_compensation +
    0.25 *
    mlbpa_market_freedom +
    0.15 *
    mlbpa_early_pay +
    0.20 *
    mlbpa_player_rights +
    0.10 *
    mlbpa_spending_incentives

  mlb_score <-
    clamp(
      mlb_score,
      0,
      100
    )

  mlbpa_score <-
    clamp(
      mlbpa_score,
      0,
      100
    )

  compromise_score <-
    min(
      mlb_score,
      mlbpa_score
    )

  support_gap <-
    abs(
      mlb_score -
        mlbpa_score
    )

  negotiation_viability <-
    clamp(
      compromise_score -
        0.20 *
        support_gap,
      0,
      100
    )

  list(
    mlb = mlb_score,
    mlbpa = mlbpa_score,
    compromise = compromise_score,
    viability = negotiation_viability,
    gap = support_gap,

    mlb_components =
      tibble(
        Component =
          c(
            "Competitive balance and payroll compression",
            "Club payroll and cost impact",
            "Revenue structure and media",
            "Alignment with MLB negotiating positions"
          ),
        Weight =
          c(
            30,
            25,
            20,
            25
          ),
        Score =
          c(
            mlb_balance,
            mlb_club_cost,
            mlb_revenue_structure,
            mlb_policy_alignment
          )
      ),

    mlbpa_components =
      tibble(
        Component =
          c(
            "Modeled player compensation",
            "Player labor-market freedom",
            "Minimum salaries and Pre-Arbitration Bonus Program",
            "Salary arbitration, free agency and Draft Pick Compensation",
            "Spending and revenue-sharing incentives"
          ),
        Weight =
          c(
            30,
            25,
            15,
            20,
            10
          ),
        Score =
          c(
            mlbpa_compensation,
            mlbpa_market_freedom,
            mlbpa_early_pay,
            mlbpa_player_rights,
            mlbpa_spending_incentives
          )
      )
  )
}

policy_label <- function(policy) {
  upper <-
    switch(
      policy$upper_rule,
      "cap" = "Salary Cap",
      "cbt" = "Competitive Balance Tax (CBT)",
      "none" = "No Upper Payroll Restriction"
    )

  lower <-
    switch(
      policy$lower_rule,
      "floor" = "Payroll Floor",
      "tax" = "Low-Spending Tax",
      "none" = "No Lower Payroll Restriction"
    )

  paste0(
    upper,
    " + ",
    lower
  )
}

