server <- function(
    input,
    output,
    session
) {

  current_policy <- reactive({

    upper_value <-
      if (input$upper_rule == "cap") {
        input$cap_value
      } else if (input$upper_rule == "cbt") {
        input$cbt_value
      } else {
        NA_real_
      }

    upper_tax_rate <-
      if (input$upper_rule == "cbt") {
        input$cbt_rate
      } else {
        0
      }

    lower_value <-
      if (input$lower_rule == "floor") {
        input$floor_value
      } else if (input$lower_rule == "tax") {
        input$low_benchmark
      } else {
        NA_real_
      }

    lower_tax_rate <-
      if (input$lower_rule == "tax") {
        input$low_tax_rate
      } else {
        0
      }

    list(
      upper_rule = input$upper_rule,
      upper_value = upper_value,
      upper_tax_rate = upper_tax_rate,
      lower_rule = input$lower_rule,
      lower_value = lower_value,
      lower_tax_rate = lower_tax_rate,
      revenue_sharing = input$revenue_sharing,
      required_spending = input$required_spending,
      central_media = input$central_media,
      player_revenue_share = input$player_revenue_share,
      minimum_salary_under2 = input$minimum_salary_under2,
      minimum_salary_2plus = input$minimum_salary_2plus,
      prearb_pool = input$prearb_pool,
      arbitration = input$arbitration,
      free_agency = input$free_agency,
      qualifying_offer = input$qualifying_offer
    )
  })

  observe({

    if (
      input$upper_rule == "cap" &&
      input$lower_rule == "floor"
    ) {

      req(
        input$cap_value,
        input$floor_value
      )

      if (
        input$floor_value >=
        input$cap_value
      ) {

        updateSliderInput(
          session,
          "cap_value",
          value =
            min(
              400,
              input$floor_value + 5
            )
        )
      }
    }
  })

  simulation <- reactive({

    simulate_policy(
      current_policy(),
      payroll_coef = payroll_effect,
      behavior_multiplier = input$behavior_response,
      full = TRUE
    )
  })

  scores <- reactive({

    negotiation_scores(
      current_policy(),
      simulation()$metrics
    )
  })

  best_result <- reactiveVal(NULL)

  observeEvent(
    input$load_current,
    {

      p <- current_cba_policy()

      updateSelectInput(
        session,
        "upper_rule",
        selected = p$upper_rule
      )

      updateSliderInput(
        session,
        "cbt_value",
        value = p$upper_value
      )

      updateSliderInput(
        session,
        "cbt_rate",
        value = p$upper_tax_rate
      )

      updateSelectInput(
        session,
        "lower_rule",
        selected = p$lower_rule
      )

      updateSliderInput(
        session,
        "revenue_sharing",
        value = p$revenue_sharing
      )

      updateSliderInput(
        session,
        "required_spending",
        value = p$required_spending
      )

      updateCheckboxInput(
        session,
        "central_media",
        value = p$central_media
      )

      updateSliderInput(
        session,
        "player_revenue_share",
        value = p$player_revenue_share
      )

      updateSliderInput(
        session,
        "minimum_salary_under2",
        value = p$minimum_salary_under2
      )

      updateSliderInput(
        session,
        "minimum_salary_2plus",
        value = p$minimum_salary_2plus
      )

      updateSliderInput(
        session,
        "prearb_pool",
        value = p$prearb_pool
      )

      updateSelectInput(
        session,
        "arbitration",
        selected = p$arbitration
      )

      updateSelectInput(
        session,
        "free_agency",
        selected = p$free_agency
      )

      updateCheckboxInput(
        session,
        "qualifying_offer",
        value = p$qualifying_offer
      )
    }
  )

  observeEvent(
    input$load_mlb,
    {

      p <- mlb_proposal_policy()

      updateSelectInput(
        session,
        "upper_rule",
        selected = p$upper_rule
      )

      updateSliderInput(
        session,
        "cap_value",
        value = p$upper_value
      )

      updateSelectInput(
        session,
        "lower_rule",
        selected = p$lower_rule
      )

      updateSliderInput(
        session,
        "floor_value",
        value = p$lower_value
      )

      updateSliderInput(
        session,
        "revenue_sharing",
        value = p$revenue_sharing
      )

      updateSliderInput(
        session,
        "required_spending",
        value = p$required_spending
      )

      updateCheckboxInput(
        session,
        "central_media",
        value = p$central_media
      )

      updateSliderInput(
        session,
        "player_revenue_share",
        value = p$player_revenue_share
      )

      updateSliderInput(
        session,
        "minimum_salary_under2",
        value = p$minimum_salary_under2
      )

      updateSliderInput(
        session,
        "minimum_salary_2plus",
        value = p$minimum_salary_2plus
      )

      updateSliderInput(
        session,
        "prearb_pool",
        value = p$prearb_pool
      )

      updateSelectInput(
        session,
        "arbitration",
        selected = p$arbitration
      )

      updateSelectInput(
        session,
        "free_agency",
        selected = p$free_agency
      )

      updateCheckboxInput(
        session,
        "qualifying_offer",
        value = p$qualifying_offer
      )
    }
  )

  observeEvent(
    input$reset_inputs,
    {

      updateSelectInput(
        session,
        "upper_rule",
        selected = "cbt"
      )

      updateSliderInput(
        session,
        "cbt_value",
        value = 244
      )

      updateSliderInput(
        session,
        "cbt_rate",
        value = 20
      )

      updateSelectInput(
        session,
        "lower_rule",
        selected = "none"
      )

      updateSliderInput(
        session,
        "revenue_sharing",
        value = 20
      )

      updateSliderInput(
        session,
        "required_spending",
        value = 50
      )

      updateCheckboxInput(
        session,
        "central_media",
        value = FALSE
      )

      updateSliderInput(
        session,
        "player_revenue_share",
        value = 50
      )

      updateSliderInput(
        session,
        "minimum_salary_under2",
        value = 0.90
      )

      updateSliderInput(
        session,
        "minimum_salary_2plus",
        value = 1.00
      )

      updateSliderInput(
        session,
        "prearb_pool",
        value = 65
      )

      updateSelectInput(
        session,
        "arbitration",
        selected = "3"
      )

      updateSelectInput(
        session,
        "free_agency",
        selected = "5_age30"
      )

      updateCheckboxInput(
        session,
        "qualifying_offer",
        value = FALSE
      )

      updateSliderInput(
        session,
        "behavior_response",
        value = 1
      )
    }
  )

  observeEvent(
    input$find_best,
    {

      fixed_terms <- current_policy()

      upper_candidates <-
        bind_rows(
          tibble(
            upper_rule = "cap",
            upper_value =
              c(
                220,
                250,
                280
              ),
            upper_tax_rate = 0
          ),

          tidyr::crossing(
            upper_rule = "cbt",
            upper_value =
              c(
                220,
                250,
                280
              ),
            upper_tax_rate =
              c(
                20,
                40,
                60
              )
          ),

          tibble(
            upper_rule = "none",
            upper_value = NA_real_,
            upper_tax_rate = 0
          )
        )

      lower_candidates <-
        bind_rows(
          tibble(
            lower_rule = "floor",
            lower_value =
              c(
                120,
                150,
                180
              ),
            lower_tax_rate = 0
          ),

          tidyr::crossing(
            lower_rule = "tax",
            lower_value =
              c(
                120,
                150,
                180
              ),
            lower_tax_rate =
              c(
                20,
                40,
                60
              )
          ),

          tibble(
            lower_rule = "none",
            lower_value = NA_real_,
            lower_tax_rate = 0
          )
        )

      candidates <-
        merge(
          upper_candidates,
          lower_candidates,
          by = NULL
        ) %>%
        tidyr::crossing(
          revenue_sharing =
            c(
              10,
              20,
              30
            ),
          required_spending =
            c(
              25,
              50,
              75
            )
        ) %>%
        filter(
          !(
            upper_rule == "cap" &
              lower_rule == "floor" &
              upper_value <= lower_value
          )
        ) %>%
        mutate(
          candidate_id =
            row_number()
        )

      payroll_low <-
        max(
          0.001,
          payroll_effect -
            payroll_effect_se
        )

      payroll_high <-
        payroll_effect +
        payroll_effect_se

      behavior_low <-
        max(
          0.25,
          input$behavior_response *
            0.75
        )

      behavior_high <-
        min(
          2,
          input$behavior_response *
            1.25
        )

      assumptions <-
        tidyr::crossing(
          payroll_coef =
            c(
              payroll_low,
              payroll_effect,
              payroll_high
            ),
          behavior =
            c(
              behavior_low,
              input$behavior_response,
              behavior_high
            )
        ) %>%
        mutate(
          assumption_id =
            row_number()
        )

      result_rows <-
        withProgress(
          message = "Testing CBA packages...",
          value = 0,
          {

            lapply(
              seq_len(
                nrow(candidates)
              ),
              function(i) {

                candidate <-
                  candidates[
                    i,
                  ]

                policy <-
                  fixed_terms

                policy$upper_rule <-
                  candidate$upper_rule

                policy$upper_value <-
                  candidate$upper_value

                policy$upper_tax_rate <-
                  candidate$upper_tax_rate

                policy$lower_rule <-
                  candidate$lower_rule

                policy$lower_value <-
                  candidate$lower_value

                policy$lower_tax_rate <-
                  candidate$lower_tax_rate

                policy$revenue_sharing <-
                  candidate$revenue_sharing

                policy$required_spending <-
                  candidate$required_spending

                candidate_results <-
                  lapply(
                    seq_len(
                      nrow(assumptions)
                    ),
                    function(j) {

                      assumption <-
                        assumptions[
                          j,
                        ]

                      sim <-
                        simulate_policy(
                          policy,
                          payroll_coef =
                            assumption$payroll_coef,
                          behavior_multiplier =
                            assumption$behavior,
                          full = FALSE
                        )

                      negotiation <-
                        negotiation_scores(
                          policy,
                          sim$metrics
                        )

                      tibble(
                        candidate_id =
                          candidate$candidate_id,
                        assumption_id =
                          assumption$assumption_id,
                        balance =
                          sim$metrics$competitive_balance_change,
                        player_comp =
                          sim$metrics$player_comp_change,
                        club_effect =
                          sim$metrics$club_effect,
                        gini =
                          sim$metrics$gini,
                        efficiency =
                          sim$metrics$recipient_marginal_wins,
                        mlb_support =
                          negotiation$mlb,
                        mlbpa_support =
                          negotiation$mlbpa,
                        compromise =
                          negotiation$compromise,
                        viability =
                          negotiation$viability
                      )
                    }
                  )

                incProgress(
                  1 /
                    nrow(candidates)
                )

                bind_rows(
                  candidate_results
                )
              }
            )
          }
        )

      all_results <-
        bind_rows(
          result_rows
        ) %>%
        group_by(
          assumption_id
        ) %>%
        mutate(
          balance_score =
            rescale01(balance),

          player_score =
            rescale01(player_comp),

          club_score =
            rescale01(club_effect),

          economic_score =
            pmin(
              balance_score,
              player_score,
              club_score
            ),

          economic_rank =
            min_rank(
              desc(economic_score)
            )
        ) %>%
        ungroup()

      summary_table <-
        all_results %>%
        group_by(
          candidate_id
        ) %>%
        summarise(
          top3_economic_share =
            mean(
              economic_rank <=
                3
            ),

          median_economic =
            median(
              economic_score
            ),

          median_balance =
            median(balance),

          balance_positive_share =
            mean(
              balance >=
                0
            ),

          median_player_comp =
            median(
              player_comp
            ),

          player_positive_share =
            mean(
              player_comp >=
                0
            ),

          median_club_effect =
            median(
              club_effect
            ),

          median_mlb_support =
            median(
              mlb_support
            ),

          median_mlbpa_support =
            median(
              mlbpa_support
            ),

          median_compromise =
            median(
              compromise
            ),

          median_viability =
            median(
              viability
            ),

          negotiable_share =
            mean(
              mlb_support >= 60 &
                mlbpa_support >= 60
            ),

          median_gini =
            median(gini),

          median_efficiency =
            if (
              all(
                is.na(efficiency)
              )
            ) {
              NA_real_
            } else {
              median(
                efficiency,
                na.rm = TRUE
              )
            },

          .groups = "drop"
        ) %>%
        left_join(
          candidates,
          by = "candidate_id"
        )

      feasible <-
        summary_table %>%
        filter(
          median_balance >= 0,
          median_player_comp >= 0,
          median_mlb_support >= 60,
          median_mlbpa_support >= 60,
          negotiable_share >= 2 / 3
        )

      if (nrow(feasible) == 0) {
        feasible <-
          summary_table %>%
          filter(
            median_mlb_support >= 55,
            median_mlbpa_support >= 55,
            median_balance >= 0,
            median_player_comp >= 0
          )
      }

      if (nrow(feasible) == 0) {
        feasible <-
          summary_table
      }

      best <-
        feasible %>%
        arrange(
          desc(median_economic),
          desc(top3_economic_share),
          desc(median_compromise),
          desc(median_viability),
          desc(median_balance)
        ) %>%
        slice(1)

      recommended_policy <-
        fixed_terms

      recommended_policy$upper_rule <-
        best$upper_rule

      recommended_policy$upper_value <-
        best$upper_value

      recommended_policy$upper_tax_rate <-
        best$upper_tax_rate

      recommended_policy$lower_rule <-
        best$lower_rule

      recommended_policy$lower_value <-
        best$lower_value

      recommended_policy$lower_tax_rate <-
        best$lower_tax_rate

      recommended_policy$revenue_sharing <-
        best$revenue_sharing

      recommended_policy$required_spending <-
        best$required_spending

      recommended_sim <-
        simulate_policy(
          recommended_policy,
          payroll_coef = payroll_effect,
          behavior_multiplier = input$behavior_response,
          full = TRUE
        )

      recommended_scores <-
        negotiation_scores(
          recommended_policy,
          recommended_sim$metrics
        )

      best_result(
        list(
          best = best,
          policy = recommended_policy,
          simulation = recommended_sim,
          scores = recommended_scores,
          tested = nrow(candidates),
          assumptions = nrow(assumptions)
        )
      )
    }
  )

  output$policy_name <- renderText({
    policy_label(
      current_policy()
    )
  })

  output$gini <- renderText({
    fmt3(
      simulation()$metrics$gini
    )
  })

  output$win_spread <- renderText({
    paste0(
      fmt2(
        simulation()$metrics$win_spread
      ),
      " wins"
    )
  })

  output$balance_change <- renderText({
    percent_text(
      simulation()$metrics$competitive_balance_change,
      1
    )
  })

  output$player_comp <- renderText({
    paste0(
      "$",
      fmt2(
        simulation()$metrics$player_comp /
          1000
      ),
      "B"
    )
  })

  output$payroll_change <- renderText({
    money_text(
      simulation()$metrics$payroll_change,
      1
    )
  })

  output$revenue_change <- renderText({
    money_text(
      simulation()$metrics$revenue_change,
      1
    )
  })

  output$cbt_exposure <- renderText({
    paste0(
      "$",
      fmt1(
        simulation()$metrics$cbt_tax
      ),
      "M"
    )
  })

  output$low_tax_exposure <- renderText({
    paste0(
      "$",
      fmt1(
        simulation()$metrics$low_spending_tax
      ),
      "M"
    )
  })

  output$what_changed <- renderUI({

    m <- simulation()$metrics
    team <- simulation()$team

    payroll_up <-
      sum(
        team$Payroll_Change_M >
          0.01
      )

    payroll_down <-
      sum(
        team$Payroll_Change_M <
          -0.01
      )

    tags$ul(

      tags$li(
        paste0(
          payroll_up,
          " clubs increase payroll and ",
          payroll_down,
          " clubs reduce payroll."
        )
      ),

      tags$li(
        paste0(
          "Total MLB payroll changes by ",
          money_text(
            m$payroll_change,
            1
          ),
          "."
        )
      ),

      tags$li(
        paste0(
          "Win Total Spread changes from ",
          fmt2(
            baseline_win_spread
          ),
          " wins to ",
          fmt2(
            m$win_spread
          ),
          " wins."
        )
      ),

      tags$li(
        paste0(
          "Competitive Balance Change is ",
          percent_text(
            m$competitive_balance_change,
            1
          ),
          "."
        )
      ),

      tags$li(
        paste0(
          "Modeled player compensation changes by ",
          money_text(
            m$player_comp_change,
            1
          ),
          "."
        )
      )
    )
  })

  output$payroll_plot <- renderPlotly({

    plot_data <-
      simulation()$team %>%
      mutate(
        x_group =
          round(
            Payroll_Change_M,
            2
          ),

        y_group =
          round(
            Change_Wins,
            2
          )
      ) %>%
      group_by(
        x_group,
        y_group
      ) %>%
      mutate(
        overlap_count = n(),

        overlap_number =
          row_number(),

        angle =
          ifelse(
            overlap_count > 1,
            2 *
              pi *
              (
                overlap_number -
                  1
              ) /
              overlap_count,
            0
          ),

        Plot_X =
          Payroll_Change_M +
          ifelse(
            overlap_count > 1,
            0.8 *
              cos(angle),
            0
          ),

        Plot_Y =
          Change_Wins +
          ifelse(
            overlap_count > 1,
            0.06 *
              sin(angle),
            0
          )
      ) %>%
      ungroup() %>%
      mutate(
        hover =
          paste0(
            "<b>",
            Team_Name,
            "</b>",

            "<br>2025 Payroll: $",
            fmt1(
              Original_Payroll_M
            ),
            "M",

            "<br>Simulated Payroll: $",
            fmt1(
              New_Payroll_M
            ),
            "M",

            "<br>Payroll Change: ",
            money_text(
              Payroll_Change_M,
              1
            ),

            "<br>Predicted Wins: ",
            fmt1(
              Predicted_Wins
            ),

            "<br>Predicted Win Change: ",
            ifelse(
              Change_Wins > 0,
              "+",
              ""
            ),
            fmt2(
              Change_Wins
            ),

            "<br>Predicted Revenue Change: ",
            money_text(
              Revenue_Change_M,
              1
            )
          )
      )

    plot_ly(
      data = plot_data,
      x = ~Plot_X,
      y = ~Plot_Y,
      type = "scatter",
      mode = "markers",
      text = ~hover,
      hoverinfo = "text",
      marker =
        list(
          size = 11,
          opacity = 0.80
        )
    ) %>%
      layout(
        xaxis =
          list(
            title =
              "Payroll Change ($M)",
            zeroline =
              TRUE
          ),

        yaxis =
          list(
            title =
              "Predicted Win Change",
            zeroline =
              TRUE
          ),

        hovermode =
          "closest",

        annotations =
          list(
            list(
              x = 0,
              y = -0.15,
              xref = "paper",
              yref = "paper",
              text =
                "Clubs with identical model results are slightly separated visually. Hover values show the exact model results.",
              showarrow = FALSE,
              xanchor = "left",
              font =
                list(
                  size = 11
                )
            )
          ),

        margin =
          list(
            b = 100
          )
      )
  })

  output$impact_table <- renderDT({

    simulation()$team %>%
      arrange(
        desc(
          abs(Change_Wins)
        )
      ) %>%
      slice_head(
        n = 10
      ) %>%
      transmute(
        Club = Team_Name,

        `2025 Payroll ($M)` =
          round(
            Original_Payroll_M,
            1
          ),

        `Simulated Payroll ($M)` =
          round(
            New_Payroll_M,
            1
          ),

        `Payroll Change ($M)` =
          round(
            Payroll_Change_M,
            1
          ),

        `Predicted Win Change` =
          round(
            Change_Wins,
            2
          ),

        `Revenue Change ($M)` =
          round(
            Revenue_Change_M,
            1
          )
      ) %>%
      datatable(
        rownames = FALSE,
        options =
          list(
            paging = FALSE,
            searching = FALSE,
            info = FALSE,
            ordering = TRUE
          )
      )
  })

  output$team_table <- renderDT({

    table_data <-
      simulation()$team %>%
      transmute(
        Club = Team_Name,

