        current_policy_fixed,
        payroll_coef = payroll_effect,
        behavior_multiplier = input$behavior_response,
        full = FALSE
      )

    proposal_sim <-
      simulate_policy(
        proposal_policy,
        payroll_coef = payroll_effect,
        behavior_multiplier = input$behavior_response,
        full = FALSE
      )

    current_scores_fixed <-
      negotiation_scores(
        current_policy_fixed,
        current_sim$metrics
      )

    proposal_scores <-
      negotiation_scores(
        proposal_policy,
        proposal_sim$metrics
