              1
            ),

            paste0(
              "$",
              fmt2(
                proposal_sim$metrics$player_comp /
                  1000
              ),
              "B"
            ),

            money_text(
              proposal_sim$metrics$payroll_change,
              1
            ),

            money_text(
              proposal_sim$metrics$revenue_change,
              1
            ),

            score_text(
              proposal_scores$mlb
            ),

            score_text(
              proposal_scores$mlbpa
            ),

            score_text(
              proposal_scores$compromise
            ),

            paste0(
              fmt1(
                proposal_scores$viability
              ),
              "%"
            )
          )
      )

    b <- best_result()

    if (!is.null(b)) {

      comparison$`Best Compromise` <-
        c(
          fmt3(
            b$simulation$metrics$gini
          ),

          paste0(
            fmt2(
              b$simulation$metrics$win_spread
            ),
            " wins"
          ),

          percent_text(
            b$simulation$metrics$competitive_balance_change,
            1
          ),

          paste0(
            "$",
            fmt2(
              b$simulation$metrics$player_comp /
                1000
            ),
            "B"
          ),

          money_text(
            b$simulation$metrics$payroll_change,
            1
          ),

          money_text(
            b$simulation$metrics$revenue_change,
            1
          ),

          score_text(
            b$scores$mlb
          ),

          score_text(
            b$scores$mlbpa
          ),

          score_text(
            b$scores$compromise
          ),

          paste0(
            fmt1(
              b$scores$viability
            ),
            "%"
          )
        )

    } else {

      comparison$`Best Compromise` <-
        rep(
          "Run Best Compromise",
          nrow(comparison)
        )
    }

    datatable(
      comparison,
      rownames = FALSE,
      options =
        list(
          paging = FALSE,
          searching = FALSE,
          ordering = FALSE,
          info = FALSE
        )
    )
